contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address b) public {
        require(b != address(this), "b must differ from self");
        bool ok1 = c.setOwner(address(this)); if (__ESBMC_reverted()) return;
        bool ok2 = c.setOwner(b); if (__ESBMC_reverted()) return;
        address currentOwner = c.owner(); if (__ESBMC_reverted()) return;
        assert(ok1 && ok2 && currentOwner == b);
    }
    receive() external payable {}
}

