pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address b) internal {
        vm.assume(b != address(this));
        bool ok1;
        try c.setOwner(address(this)) returns (bool __r) { ok1 = __r; } catch { return; }
        bool ok2;
        try c.setOwner(b) returns (bool __r) { ok2 = __r; } catch { return; }
        address currentOwner;
        try c.owner() returns (address __r) { currentOwner = __r; } catch { return; }
        assertTrue(ok1 && ok2 && currentOwner == b);
    }

    function testFuzz_run(address b) public {
        vm.assume(b.code.length == 0 && uint160(b) > 0xffff && b != address(this) && b != address(c) && b != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && b != 0x000000000000000000636F6e736F6c652e6c6f67 && b != 0x4e59b44847b379578588920cA78FbF26c0B4956C && b != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(b);
    }

    receive() external payable {}
}
